class Solution {
public:
    long long minCost(vector<int>& nums, vector<int>& costs) {
        int n = nums.size();
        vector<long long> dp(n, LLONG_MAX / 4);
        vector<int> inc, dec;
        dp[0] = 0;
        for (int i = 0; i < n; ++i) {
            while (!inc.empty() && nums[inc.back()] <= nums[i]) {
                dp[i] = min(dp[i], dp[inc.back()] + costs[i]); inc.pop_back();
            }
            while (!dec.empty() && nums[dec.back()] > nums[i]) {
                dp[i] = min(dp[i], dp[dec.back()] + costs[i]); dec.pop_back();
            }
            inc.push_back(i); dec.push_back(i);
        }
        return dp[n - 1];
    }
};
